import { Type } from '@angular/core';

/* ---- Generated by tools/gen-docs.mjs ---- */

export interface DemoSource {
  file: string;
  code: string;
  html: string;
}

export interface ApiMember {
  name: string;
  kind: string;
  type: string;
  description: string;
  default?: string;
  required?: boolean;
}

export interface ApiClass {
  name: string;
  kind: string;
  selector?: string;
  description: string;
  members: ApiMember[];
}

export interface CssVarDoc {
  name: string;
  fallback: string;
}

export interface EntryData {
  api: { classes: ApiClass[]; cssVars: CssVarDoc[] };
  sources: Record<string, DemoSource>;
}

export interface TokenDoc {
  name: string;
  value: string;
  group: string;
  comment: string;
}

/** One token and its value in every style preset; `null` — the preset keeps the default. */
export interface PresetTokenRow {
  name: string;
  group: string;
  values: Record<string, string | null>;
}

/* ---- Authored per component ---- */

export interface DemoDoc {
  /** Key in `EntryData.sources` (file name without `.demo.ts`). */
  source: string;
  title: string;
  description?: string;
  component: Type<unknown>;
}

export interface KeyboardDoc {
  keys: string[];
  action: string;
}

export interface SlotDoc {
  name: string;
  description: string;
}

export interface ComponentDoc {
  slug: string;
  title: string;
  /** One or two sentences: what it is and when to use it. */
  description: string;
  /** Entry point name, e.g. `button` → `@kenny/ui/button`. */
  entry: string;
  /** Generated API of the entry point. */
  api: EntryData['api'];
  /** Generated sources of the demo files. */
  sources: Record<string, DemoSource>;
  demos: DemoDoc[];
  playground?: Type<unknown>;
  /** Limit the API tables to these classes (defaults to all in the entry point). */
  apiClasses?: string[];
  /** Names for the import line (defaults to the documented classes). */
  imports?: string[];
  /** Only list CSS variables with this prefix (when an entry point holds several components). */
  cssPrefix?: string;
  slots?: SlotDoc[];
  keyboard?: KeyboardDoc[];
  a11y?: string[];
}
